mapper.select:
SELECT a.menu_id AS menuId ,a.parent_id AS parentId ,a.menu_name AS menuName ,a.menu_path AS menuPath ,a.icon AS icon ,a.sort_order AS sortOrder ,a.menu_level AS menuLevel ,a.menu_type AS menuType ,a.use_yn AS useYn FROM tb_menu_mst a WHERE 1 = 1
AND a.menu_name LIKE '%' + #{menuName} + '%'
AND a.menu_type = #{menuType}
AND a.use_yn = #{useYn}
ORDER BY a.menu_level ,a.parent_id ,a.sort_order

mapper.update:
UPDATE tb_menu_mst
SET    parent_id  = #{parentId}
      ,menu_name  = #{menuName}
      ,menu_path  = #{menuPath}
      ,icon       = #{icon}
      ,sort_order = #{sortOrder}
      ,menu_level = #{menuLevel}
      ,menu_type  = #{menuType}
      ,use_yn     = #{useYn}
      ,upd_id     = 'SYSTEM'
      ,upd_dt     = GETDATE()
WHERE menu_id = #{menuId}

UPDATE tb_menu_mst
SET    use_yn   = #{useYn}
      ,upd_id   = 'SYSTEM'
      ,upd_dt   = GETDATE()
WHERE menu_id   = #{menuId}
